namespace LumaDesk {
public class CloudLocation {public string City="Москва";public double Lat=55.7522,Lon=37.6156;}
public class CloudSettings {public bool Seconds=true,Sound=true,Snapping=true;public int Opacity=84,Refresh=30,WeatherMode=0;public CloudLocation Location=new CloudLocation();}
public class CloudEvent {public string Id,Title,Kind,Sound="@dawn",NextLocal;public int Days,Snooze=5;public bool Enabled=true;}
public class CloudDocument {public int schema=2;public List<Note> notes=new List<Note>();public List<CloudEvent> items=new List<CloudEvent>();public CloudSettings settings=new CloudSettings();}
public class CloudSnapshot {public long revision,updated_at;public CloudDocument document=new CloudDocument();}
public class CloudSession {public string token,username;public long user_id,expires_at;}
public class CloudAccount {public string Server="",Username="",ProtectedToken="",DeviceId=Guid.NewGuid().ToString("N");public long UserId,Revision;public CloudDocument Baseline;}
public class CloudWrite {public long expected_revision;public CloudDocument document;}
public class CloudApiException:Exception {public int Code;public CloudApiException(int code,string message):base(message){Code=code;}}
public static class CloudJson {
 public static JavaScriptSerializer New(){return new JavaScriptSerializer{MaxJsonLength=2097152};}
 public static string Write(object value){return New().Serialize(value);}public static T Copy<T>(T value){return New().Deserialize<T>(Write(value));}
 public static bool Same(object a,object b){return Write(a)==Write(b);}
 public static void Atomic(string path,string text){Directory.CreateDirectory(Path.GetDirectoryName(path));string temp=path+".tmp";File.WriteAllText(temp,text,Encoding.UTF8);if(File.Exists(path))File.Replace(temp,path,path+".bak");else File.Move(temp,path);}
}
public static class CloudMerge {
 public static CloudDocument Capture(State s){var doc=new CloudDocument{settings=new CloudSettings{Seconds=s.Seconds,Sound=s.Sound,Snapping=s.Snapping,Opacity=s.Opacity,Refresh=s.Refresh,WeatherMode=s.WeatherMode,Location=new CloudLocation{City=s.City,Lat=s.Lat,Lon=s.Lon}}};foreach(var a in s.Items.OrderBy(a=>a.Id,StringComparer.Ordinal))doc.items.Add(new CloudEvent{Id=a.Id,Title=a.Title,Kind=a.Kind,Sound=Melodies.Index(a.Sound)>=0?Melodies.Ids[Melodies.Index(a.Sound)]:"@dawn",NextLocal=a.NextLocal,Days=a.Days,Enabled=a.Enabled,Snooze=a.Snooze});doc.notes=(s.Notes??new List<Note>()).Select(n=>CloudJson.Copy(n)).OrderBy(n=>n.Id,StringComparer.Ordinal).ToList();return doc;}
 public static void Apply(State s,CloudDocument doc){var local=s.Items.ToDictionary(a=>a.Id,a=>a);var items=new List<Item>();foreach(var c in doc.items){Item old;string sound=c.Sound;if(local.TryGetValue(c.Id,out old)&&!string.IsNullOrEmpty(old.Sound)&&Melodies.Index(old.Sound)<0)sound=old.Sound;var a=new Item{Id=c.Id,Title=c.Title,Kind=c.Kind,Sound=sound,Days=c.Days,Enabled=c.Enabled,Snooze=c.Snooze};a.NextLocal=c.NextLocal;items.Add(a);}s.Items=items;s.Notes=(doc.notes??new List<Note>()).Select(n=>CloudJson.Copy(n)).ToList();var p=doc.settings;s.Seconds=p.Seconds;s.Sound=p.Sound;s.Snapping=p.Snapping;s.Opacity=p.Opacity;s.Refresh=p.Refresh;s.WeatherMode=p.WeatherMode;s.City=p.Location.City;s.Lat=p.Location.Lat;s.Lon=p.Location.Lon;}
 static T Pick<T>(T baseline,T local,T remote){return CloudJson.Same(local,baseline)?remote:local;}
 static CloudEvent ConflictCopy(CloudEvent source){var copy=CloudJson.Copy(source);using(var hash=SHA256.Create()){var bytes=hash.ComputeHash(Encoding.UTF8.GetBytes(source.Id+"|"+CloudJson.Write(source)));copy.Id=BitConverter.ToString(bytes,0,16).Replace("-","").ToLowerInvariant();}string title=source.Title;if(title.Length>120)title=title.Substring(0,120);copy.Title=title+" (копия конфликта)";return copy;}
 static Dictionary<string,CloudEvent> Map(CloudDocument doc){return doc.items.ToDictionary(a=>a.Id,a=>a);}
 public static CloudDocument Merge(CloudDocument baseline,CloudDocument local,CloudDocument remote,out int conflicts){conflicts=0;var b=Map(baseline);var l=Map(local);var r=Map(remote);var output=new Dictionary<string,CloudEvent>();foreach(string id in b.Keys.Union(l.Keys).Union(r.Keys).OrderBy(a=>a,StringComparer.Ordinal)){CloudEvent be=null,le=null,re=null;b.TryGetValue(id,out be);l.TryGetValue(id,out le);r.TryGetValue(id,out re);CloudEvent take=null;if(CloudJson.Same(le,be))take=re;else if(CloudJson.Same(re,be)||CloudJson.Same(le,re))take=le;else{conflicts++;if(le!=null&&re!=null){output[re.Id]=CloudJson.Copy(re);var clone=ConflictCopy(le);output[clone.Id]=clone;}else{var clone=ConflictCopy(le??re);output[clone.Id]=clone;}continue;}if(take!=null)output[take.Id]=CloudJson.Copy(take);}
 int noteConflicts;var notes=NotesModel.Merge(baseline.notes,local.notes,remote.notes,out noteConflicts);conflicts+=noteConflicts;var bs=baseline.settings;var ls=local.settings;var rs=remote.settings;return new CloudDocument{notes=notes,items=output.Values.OrderBy(a=>a.Id,StringComparer.Ordinal).ToList(),settings=new CloudSettings{Seconds=Pick(bs.Seconds,ls.Seconds,rs.Seconds),Sound=Pick(bs.Sound,ls.Sound,rs.Sound),Snapping=Pick(bs.Snapping,ls.Snapping,rs.Snapping),Opacity=Pick(bs.Opacity,ls.Opacity,rs.Opacity),Refresh=Pick(bs.Refresh,ls.Refresh,rs.Refresh),WeatherMode=Pick(bs.WeatherMode,ls.WeatherMode,rs.WeatherMode),Location=CloudJson.Copy(Pick(bs.Location,ls.Location,rs.Location))}};}
 public static CloudDocument Initial(CloudDocument local,CloudSnapshot remote,bool import){var doc=CloudJson.Copy(remote.document);if(remote.revision==0)doc.settings=CloudJson.Copy(local.settings);if(import){var map=Map(doc);foreach(var a in local.items){CloudEvent existing;if(!map.TryGetValue(a.Id,out existing))map[a.Id]=CloudJson.Copy(a);else if(!CloudJson.Same(a,existing)){var copy=ConflictCopy(a);map[copy.Id]=copy;}}doc.items=map.Values.OrderBy(a=>a.Id,StringComparer.Ordinal).ToList();}doc.notes=NotesModel.Initial(doc.notes??new List<Note>(),local.notes??new List<Note>(),import);return doc;}
}
public static class CloudApi {
 public static string ValidateServer(string value){Uri uri;if(!Uri.TryCreate(value.Trim(),UriKind.Absolute,out uri)||!string.IsNullOrEmpty(uri.UserInfo)||!string.IsNullOrEmpty(uri.Query)||!string.IsNullOrEmpty(uri.Fragment))throw new Exception("Введи адрес сервера вида https://sync.example.ru");bool loop=uri.Host=="localhost"||uri.Host=="127.0.0.1"||uri.Host=="[::1]"||uri.Host=="::1";if(uri.Scheme!="https"&&!(uri.Scheme=="http"&&loop))throw new Exception("Для удалённого сервера нужен HTTPS.");return uri.AbsoluteUri.TrimEnd('/');}
 public static T Send<T>(string server,string method,string path,object payload,string token){server=ValidateServer(server);ServicePointManager.SecurityProtocol=SecurityProtocolType.Tls12;var request=(HttpWebRequest)WebRequest.Create(server+path);request.Method=method;request.Accept="application/json";request.Timeout=15000;request.ReadWriteTimeout=15000;request.AllowAutoRedirect=false;if(request.RequestUri.IsLoopback)request.Proxy=null;request.AutomaticDecompression=DecompressionMethods.GZip|DecompressionMethods.Deflate;request.UserAgent="LumaDesk/3.1.5";if(!string.IsNullOrEmpty(token))request.Headers[HttpRequestHeader.Authorization]="Bearer "+token;try{if(payload!=null){byte[] bytes=Encoding.UTF8.GetBytes(CloudJson.Write(payload));request.ContentType="application/json; charset=utf-8";request.ContentLength=bytes.Length;using(var stream=request.GetRequestStream())stream.Write(bytes,0,bytes.Length);}
 using(var response=(HttpWebResponse)request.GetResponse()){if((int)response.StatusCode>=300)throw new CloudApiException((int)response.StatusCode,"Сервер перенаправляет запрос. Укажи конечный HTTPS-адрес.");if(response.StatusCode==HttpStatusCode.NoContent)return default(T);string text=Read(response);var result=CloudJson.New().Deserialize<T>(text);var snapshot=(object)result as CloudSnapshot;if(snapshot!=null&&(snapshot.document==null||snapshot.document.schema!=2))throw new Exception("Нужен сервер LumaDesk 2.1 с поддержкой заметок. Обнови серверный пакет.");return result;}}
 catch(WebException e){var response=e.Response as HttpWebResponse;if(response==null)throw new Exception("Нет связи с сервером. Проверь адрес и подключение.");using(response){string message="Сервер отклонил запрос ("+(int)response.StatusCode+").";try{var body=CloudJson.New().Deserialize<Dictionary<string,object>>(Read(response));object detail;if(body.TryGetValue("detail",out detail)&&detail is string)message=(string)detail;}catch{}throw new CloudApiException((int)response.StatusCode,message);}}}
 static string Read(HttpWebResponse response){using(var stream=response.GetResponseStream())using(var buffer=new MemoryStream()){var block=new byte[8192];int read;while((read=stream.Read(block,0,block.Length))>0){if(buffer.Length+read>2097152)throw new Exception("Слишком большой ответ сервера.");buffer.Write(block,0,read);}return Encoding.UTF8.GetString(buffer.ToArray());}}
}
public static class CloudSync {
 public static CloudAccount Account=new CloudAccount();public static string Status="Войди, чтобы синхронизировать данные";public static bool Busy;static bool stopped;static System.Windows.Forms.Timer timer;static Action<bool> changed;static bool initialized,applying;static string lastSavedContent;static SyncSchedule schedule;
 static string PathName {get{return Path.Combine(Store.Dir,"account.json");}}
 public static bool Connected {get{return Account.UserId>0&&!string.IsNullOrEmpty(Account.ProtectedToken);}}
 static string Protect(string token){return Convert.ToBase64String(ProtectedData.Protect(Encoding.UTF8.GetBytes(token),null,DataProtectionScope.CurrentUser));}
 static string Token(){try{return Encoding.UTF8.GetString(ProtectedData.Unprotect(Convert.FromBase64String(Account.ProtectedToken),null,DataProtectionScope.CurrentUser));}catch{throw new CloudApiException(401,"Не удалось открыть ключ сеанса. Войди заново.");}}
 static void Save(){CloudJson.Atomic(PathName,CloudJson.Write(Account));}
 public static void Initialize(Action<bool> onChanged){changed=onChanged;stopped=false;try{if(File.Exists(PathName))Account=CloudJson.New().Deserialize<CloudAccount>(File.ReadAllText(PathName))??new CloudAccount();}catch{Account=new CloudAccount();}lastSavedContent=CloudJson.Write(CloudMerge.Capture(Store.S));schedule=new SyncSchedule(DateTime.UtcNow);initialized=true;timer=new System.Windows.Forms.Timer{Interval=2000};timer.Tick+=(s,e)=>{if(Store.S.AutoSync&&Connected&&!Busy&&schedule.Due(DateTime.UtcNow))Kick();};timer.Start();if(Connected&&Store.S.AutoSync)schedule.Changed(DateTime.UtcNow);}
 public static void SetAutomatic(bool value){Store.S.AutoSync=value;Store.Save();if(value&&schedule!=null)schedule.Changed(DateTime.UtcNow);}
 public static void LocalChanged(){if(!initialized||applying||stopped)return;string content=CloudJson.Write(CloudMerge.Capture(Store.S));if(content==lastSavedContent)return;lastSavedContent=content;if(Connected)schedule.Changed(DateTime.UtcNow);}
 public static void Stop(){stopped=true;initialized=false;if(timer!=null){timer.Stop();timer.Dispose();timer=null;}}
 public static async void Kick(){await Synchronize();}
 static void Apply(CloudDocument doc){if(CloudJson.Same(CloudMerge.Capture(Store.S),doc))return;bool weather=Store.S.Lat!=doc.settings.Location.Lat||Store.S.Lon!=doc.settings.Location.Lon||Store.S.WeatherMode!=doc.settings.WeatherMode;applying=true;try{CloudMerge.Apply(Store.S,doc);Store.SaveStrict();lastSavedContent=CloudJson.Write(CloudMerge.Capture(Store.S));}finally{applying=false;}if(changed!=null)changed(weather);}
 public static async Task<bool> Connect(string server,string username,string password,bool register,bool import){if(Busy)return false;try{server=CloudApi.ValidateServer(server);}catch(Exception e){Status=e.Message;return false;}Busy=true;string issued=null;CloudDocument before=null;try{before=CloudMerge.Capture(Store.S);Status=register?"Создаём аккаунт…":"Входим…";string device=Account.DeviceId;var session=await Task.Run(()=>CloudApi.Send<CloudSession>(server,"POST",register?"/v1/auth/register":"/v1/auth/login",new {username=username,password=password,device_id=device},null));issued=session.token;string protectedToken=await Task.Run(()=>Protect(session.token));CloudSnapshot accepted=null;
 for(int attempt=0;attempt<3;attempt++){var remote=await Task.Run(()=>CloudApi.Send<CloudSnapshot>(server,"GET","/v1/sync",null,issued));CloudDocument initial;int reconnectConflicts;if(!register&&Account.UserId==session.user_id&&Account.Username==session.username&&Account.Server==server&&Account.Baseline!=null)initial=CloudMerge.Merge(Account.Baseline,before,remote.document,out reconnectConflicts);else initial=CloudMerge.Initial(before,remote,import);try{accepted=await Task.Run(()=>CloudApi.Send<CloudSnapshot>(server,"PUT","/v1/sync",new CloudWrite{expected_revision=remote.revision,document=initial},issued));break;}catch(CloudApiException e){if(e.Code!=409||attempt==2)throw;}}
 if(stopped)return false;CloudJson.Atomic(Path.Combine(Store.Dir,"backups","before-account-"+DateTime.UtcNow.ToString("yyyyMMdd-HHmmss-fff")+".json"),Store.Json.Serialize(Store.S));int conflicts;var final=CloudMerge.Merge(before,CloudMerge.Capture(Store.S),accepted.document,out conflicts);Apply(final);Account=new CloudAccount{Server=server,Username=session.username,UserId=session.user_id,DeviceId=device,ProtectedToken=protectedToken,Revision=accepted.revision,Baseline=accepted.document};Save();if(schedule!=null)schedule.Complete(DateTime.UtcNow,true,!CloudJson.Same(final,accepted.document));Status="Синхронизировано · "+DateTime.Now.ToString("HH:mm");issued=null;return true;
 }catch(Exception e){Status=e.Message;if(issued!=null)try{await Task.Run(()=>CloudApi.Send<object>(server,"POST","/v1/auth/logout",null,issued));}catch{}return false;}finally{Busy=false;}}
 public static async Task<bool> Synchronize(){if(stopped||Busy||!Connected)return false;Busy=true;try{Status="Синхронизация…";string server=Account.Server;string token=await Task.Run(()=>Token());if(stopped)return false;var baseline=Account.Baseline??new CloudDocument();var sent=CloudMerge.Capture(Store.S);CloudSnapshot accepted=null;int conflicts=0;
 for(int attempt=0;attempt<3;attempt++){var remote=await Task.Run(()=>CloudApi.Send<CloudSnapshot>(server,"GET","/v1/sync",null,token));int c;var merged=CloudMerge.Merge(baseline,sent,remote.document,out c);conflicts=c;if(CloudJson.Same(merged,remote.document)){accepted=remote;break;}try{accepted=await Task.Run(()=>CloudApi.Send<CloudSnapshot>(server,"PUT","/v1/sync",new CloudWrite{expected_revision=remote.revision,document=merged},token));break;}catch(CloudApiException e){if(e.Code!=409||attempt==2)throw;}}
 if(stopped)return false;int later;var final=CloudMerge.Merge(sent,CloudMerge.Capture(Store.S),accepted.document,out later);Apply(final);if(Account.Revision!=accepted.revision||Account.Baseline==null){Account.Revision=accepted.revision;Account.Baseline=accepted.document;Save();}if(schedule!=null)schedule.Complete(DateTime.UtcNow,true,!CloudJson.Same(final,accepted.document));Status="Синхронизировано · "+DateTime.Now.ToString("HH:mm")+(conflicts+later>0?" · сохранены копии конфликтов":"");return true;
 }catch(CloudApiException e){if(schedule!=null)schedule.Complete(DateTime.UtcNow,false,true);Status=e.Message;if(e.Code==401){Account.ProtectedToken="";try{Save();}catch{}}return false;}catch(Exception e){if(schedule!=null)schedule.Complete(DateTime.UtcNow,false,true);Status=e.Message;return false;}finally{Busy=false;}}
 public static async Task Logout(){if(Busy)return;Busy=true;string server=Account.Server,token=null;try{try{token=await Task.Run(()=>Token());}catch{}Account.ProtectedToken="";Account.UserId=0;Account.Revision=0;Account.Baseline=null;Save();if(token!=null)try{await Task.Run(()=>CloudApi.Send<object>(server,"POST","/v1/auth/logout",null,token));}catch{}Status="Выход выполнен на этом компьютере";}catch(Exception e){Status=e.Message;}finally{Busy=false;}}
 public static async Task<bool> ChangePassword(string oldPassword,string newPassword){if(Busy||!Connected)return false;Busy=true;try{string server=Account.Server;string token=await Task.Run(()=>Token());var session=await Task.Run(()=>CloudApi.Send<CloudSession>(server,"POST","/v1/auth/password",new {old_password=oldPassword,new_password=newPassword},token));Account.ProtectedToken=await Task.Run(()=>Protect(session.token));Save();Status="Пароль изменён. Другие устройства должны войти заново.";return true;}catch(Exception e){Status=e.Message;return false;}finally{Busy=false;}}
}
}
